code_question:
import pulp

def solution() -> tuple:
    items = [
        {'weight': 1, 'value': 5},
        {'weight': 4, 'value': 1},
        {'weight': 3, 'value': 5},
        {'weight': 5, 'value': 5},
        {'weight': 4, 'value': 4}
    ]
    capacity = 25

    prob = pulp.LpProblem('Knapsack', pulp.LpMaximize)
    x = [pulp.LpVariable(f'x{i}', cat='Binary') for i in range(len(items))]

    prob += pulp.lpSum(x[i] * items[i]['value'] for i in range(len(items)))
    prob += pulp.lpSum(x[i] * items[i]['weight'] for i in range(len(items))) <= capacity

    prob.solve(pulp.PULP_CBC_CMD(msg=False))

    if pulp.LpStatus[prob.status] == 'Optimal':
        selected = [i for i in range(len(items)) if pulp.value(x[i]) == 1]
        total_value = sum(items[i]['value'] for i in selected)
        return (True, total_value, selected)
    else:
        return (False, 0, [])

