def solution() -> dict:
    # Define graph
    graph = {
        1: [3, 4],
        2: [3, 5],
        3: [1, 2, 4, 5, 6],
        4: [1, 3, 5, 6],
        5: [2, 3, 4, 6, 8],
        6: [3, 4, 5],
        7: [],
        8: [5]
    }
    vertices = list(range(1, 9))

    # Sort vertices by degree (descending) then vertex number
    sorted_vertices = sorted(vertices, key=lambda v: (-len(graph[v]), v))

    # Available colors
    colors = ['A', 'B', 'C', 'D']
    assignment = {}

    # Greedy coloring algorithm
    for vertex in sorted_vertices:
        used_colors = set()
        for neighbor in graph[vertex]:
            if neighbor in assignment:
                used_colors.add(assignment[neighbor])
        for c in colors:
            if c not in used_colors:
                assignment[vertex] = c
                break

    return assignment

